using System.Text.Json;using Diten.DecisionIntelligenceService.Application.Modules.OutcomeTracking;using Diten.DecisionIntelligenceService.Domain.Modules.OutcomeTracking;using Xunit;
public class ProjectionTests{static readonly Guid T=Guid.NewGuid(),O=Guid.NewGuid(),V=Guid.NewGuid(),A=Guid.NewGuid();static OutcomeMeasurement M(Guid id,DateOnly end,Guid? s=null)=>new(id,T,O,V,OutcomeKind.Quantitative,new(end.AddDays(-1),end),1,null,s,s is null?null:CorrectionReason.SourceRestatement,A);
[Fact]public void All_statuses_and_effective_head_are_deterministic(){var asOf=new DateOnly(2026,8,5);Assert.Equal(ObservationStatus.NoObservation,ObservationProjector.Project([],T,O,V,asOf,30).Status);var stale=M(Guid.NewGuid(),asOf.AddDays(-31));Assert.Equal(ObservationStatus.Stale,ObservationProjector.Project([stale],T,O,V,asOf,30).Status);var corrected=M(Guid.NewGuid(),asOf,stale.Id);var a=ObservationProjector.Project([stale,corrected],T,O,V,asOf,30);var b=ObservationProjector.Rebuild([corrected,stale],T,O,V,asOf,30);Assert.Equal(ObservationStatus.Current,a.Status);Assert.Equal(JsonSerializer.SerializeToUtf8Bytes(a),JsonSerializer.SerializeToUtf8Bytes(b));}}
